settings.custom_liquid:
{%- assign vendorHandle = product.vendor | handleize -%}
{%- if collections[vendorHandle].products.size > 0 -%}
<a href="{{ collections[vendorHandle].url }}">{{ product.vendor }}</a>
{%-  endif -%}

{% if collection.handle == "mat" %}
<div style="background:#ededed;padding:10px">
  <p><b style="color:red;">-20% di sconto</b></p>
  <p><span> </span>applicato quando aggiungi l'articolo al carrello!</p>
</div>
{% endif %}
